/***
 * MARK: addProcessLog
 * @description Appends a structured log entry with a severity tag and optional project/task metadata.
 * @param {string} tag - Severity tag ([AGENT], [HUMAN], [CI/CMD], [INFO], [ERROR]).
 * @param {string} text - Log text or chunk.
 * @param {Object} [meta] - Optional metadata containing projectId, projectName, and taskId.
 ***/
const addProcessLog = useCallback((tag, text, meta = {}) => {
  if (!text) return;
  const str = String(text).trim();
  if (!str) return;

  // Detect if text already has a severity prefix like [TOOL], [RESULT], [AGENT], [INFO], [ERROR], [CI/CMD], [SYSTEM]
  let effectiveTag = meta?.tag || tag;
  let cleanText = str;
  const match = str.match(/^\[([A-Z0-9_/]+)\]\s*(.*)$/);
  if (match) {
    effectiveTag = `[${match[1]}]`;
    cleanText = match[2] || '';
  }

  const ts = new Date().toLocaleTimeString();
  const id = `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
  const projectId = meta?.projectId || null;
  const projectName = meta?.projectName || null;
  const taskId = meta?.taskId || null;
  // Runner frame identity for stored/WS dedupe (see normalizeEntries):
  // a live line is dropped once the same (executionId, seq) frame lands
  // in the task's stored entries after a refetch.
  const executionId = meta?.executionId ?? null;
  const seq = Number.isInteger(meta?.seq) ? meta.seq : null;
  const runnerId = meta?.runnerId ?? null;
  setProcessLogs((prev) => [
    ...prev.slice(-499), // Retain latest 500 lines
    {
      id,
      timestamp: ts,
      tag: effectiveTag,
      text: cleanText || str,
      raw: `${projectName ? `[${projectName}] ` : ''}${effectiveTag} ${cleanText || str}`,
      projectId,
      projectName,
      taskId,
      executionId,
      seq,
      runnerId,
    },
  ]);
}, []);

const clearLogs = useCallback(() => {
  setProcessLogs([]);
  setMessages([]);
  setToolCalls([]);
  toolNamesRef.current = {};
}, []);

/***
 * MARK: addProcessLogEntries
 * @description Appends structured log entries received live over the
 *   socket (`PROCESS_LOG_ENTRIES`: tool calls/results, thinking markers,
 *   errors, telemetry) as first-class entries. They carry the backend
 *   identity (`executionId`/`seq`/`runnerId`) so `normalizeEntries` drops
 *   each one once the same record lands in the task refetch — the same
 *   stored/live dedupe as text frames, but without re-parsing text.
 ***/
const addProcessLogEntries = useCallback((entries, meta = {}) => {
  if (!Array.isArray(entries) || entries.length === 0) return;
  const executionId = meta?.executionId ?? null;
  const seq = Number.isInteger(meta?.seq) ? meta.seq : null;
  const runnerId = meta?.runnerId ?? null;
  setProcessLogs((prev) => [
    ...prev.slice(-499), // Retain latest 500 lines
    ...entries
      .filter(Boolean)
      .map((entry) => ({
        id: entry.id != null ? `ws-entry-${entry.id}` : `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
        timestamp: entry.ts ?? new Date().toLocaleTimeString(),
        tag: null,
        text: '',
        raw: '',
        projectId: meta?.projectId ?? null,
        projectName: meta?.projectName ?? null,
        taskId: meta?.taskId ?? null,
        executionId,
        seq,
        runnerId,
        entry,
      })),
  ]);
}, []);

